const incompatibleRelationshipEndpoint = (tenantId: string, partyId: string, nextType: PartyType) => {
  // Historical relationships retain their stored endpoint IDs. Follow reverse alias
  // edges in the trusted tenant; UNION deduplicates chains before the conflict limit.
  const endpointIds = sql`(
    with recursive correction_party_endpoints(party_id) as (
      select ${partyId}::uuid
      union
      select ${partyAliases.aliasPartyId}
      from ${partyAliases}
      inner join correction_party_endpoints
        on ${partyAliases.canonicalPartyId} = correction_party_endpoints.party_id
      where ${partyAliases.tenantId} = ${tenantId}::uuid
    )
    select party_id from correction_party_endpoints
  )`;
  if (nextType === 'PERSON') {
    return inArray(partyRelationships.toPartyId, endpointIds);
  }
  if (nextType === 'ORGANIZATION') {
    return inArray(partyRelationships.fromPartyId, endpointIds);
  }
  return or(inArray(partyRelationships.fromPartyId, endpointIds), inArray(partyRelationships.toPartyId, endpointIds));
};

